import {analyze} from './core.mjs';
import {translator,formatMoney,formatNumber,formatDate} from './i18n.mjs';

const escape=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const labels={workflow:['Business workflow','วิเคราะห์ธุรกิจ'],begin:['Start analysis','เริ่มวิเคราะห์'],active:['Active report','รายงานที่ใช้งาน'],saved:['Saved work','ข้อมูลที่บันทึก'],receipts:['Receipts','ใบเสร็จ'],campaigns:['Approved campaigns','แคมเปญที่อนุมัติ'],outcomes:['Recorded outcomes','ผลลัพธ์ที่บันทึก'],average:['Items sold per day in this reporting period.','รายการที่ขายต่อวันในช่วงรายงานนี้'],edit:['Business data','ข้อมูลร้าน'],steps:[['Shop setup','ตั้งค่าร้าน'],['Channels','เลือกช่องทาง'],['Sales data','เพิ่มยอดขาย'],['Comparable prices','เทียบราคาสุทธิ'],['Profit & cash','ส่วนต่างและเงินสด'],['AI review','วิเคราะห์ด้วย AI'],['What-if','จำลองความคุ้มค่า'],['Actual results','บันทึกผลจริง']]};
export function renderStudioOverview({state,language='en',edition='a'}){
 const t=translator(language),l=key=>labels[key][language==='th'?1:0],num=value=>formatNumber(value,language),money=value=>formatMoney(value,language),date=value=>formatDate(value,language);
 const data=state.datasets.find(item=>item.id===state.activeDatasetId),a=analyze(data.menus,data.period),width=Math.max(a.weekdayDaily,a.weekendDaily,1);
 const sample=data.sourceType==='synthetic';
 return `<div class="overview-topline"><p class="eyebrow">${l('active')} / ${escape(data.name)}</p><span class="status-badge neutral">${t(sample?'demoBadge':'liveBadge')}</span></div>
  <section class="hero-scene has-window"><div class="hero-copy"><h1><span class="hero-line">${escape(state.business.name)}</span></h1><p class="studio-report-period">${date(data.period.start)} — ${date(data.period.end)}</p><div class="button-row"><button class="button" data-action="open-workflow" data-step="1">${l('begin')}<span aria-hidden="true">→</span></button><button class="button secondary" data-action="goto-advisor">${t('advisor')}</button><button class="button ghost" data-action="goto-data">${l('edit')}</button></div></div><div class="hero-art window-art"><img src="/images/studio-window.webp" width="1200" height="800" alt="" fetchpriority="high" decoding="async"></div></section>
  <div class="metric-ribbon"><div class="metric"><p class="metric-name">${t('grossSales')}</p><strong>${money(a.sales)}</strong><small>${t('beforeDiscount')}</small></div><div class="metric"><p class="metric-name">${t('soldItems')}</p><strong>${num(a.orders)}</strong><small>${num(a.rows.length)} ${t('menus')}</small></div><div class="metric"><p class="metric-name">${t('contribution')}</p><strong>${money(a.totalContribution)}</strong><small>${t('notNetProfit')}</small></div><div class="metric"><p class="metric-name">${t('dataCoverage')}</p><strong>${num(a.denominator.days)} <span class="metric-unit">${t('days')}</span></strong><small>${date(data.period.start)} — ${date(data.period.end)}</small></div></div>
  <section class="overview-workflow" aria-labelledby="overview-workflow-title" data-cinematic-reveal><div class="story-head"><h2 id="overview-workflow-title">${l('workflow')}</h2></div><ol class="merchant-step-list">${labels.steps.map((step,index)=>`<li><button data-action="open-workflow" data-step="${index+1}"><span class="workflow-number">${String(index+1).padStart(2,'0')}</span><span>${step[language==='th'?1:0]}</span><span class="step-arrow" aria-hidden="true">→</span></button></li>`).join('')}</ol></section>
  <div class="overview-story overview-evidence"><section><div class="story-head"><h2>${t('dailyRhythm')}</h2><button class="text-button" data-action="goto-analysis">${t('viewDetail')}</button></div><div class="story-body"><div><h3>${t('weekday')} / ${t('weekend')}</h3><p>${l('average')}</p></div><div class="bar-chart" role="img" aria-label="${t('weekday')}: ${formatNumber(a.weekdayDaily,language,1)}; ${t('weekend')}: ${formatNumber(a.weekendDaily,language,1)}">${[[a.weekdayDaily,'weekday'],[a.weekendDaily,'weekend']].map(([value,key])=>`<div class="bar-wrap" style="--height:${value/width*80}%"><span class="bar-value">${formatNumber(value,language,1)}</span><div class="bar" style="height:${value/width*80}%"></div><span class="bar-caption">${t(key)}</span></div>`).join('')}</div></div></section><aside><div class="story-head"><h2>${l('saved')}</h2></div><dl class="saved-work-list"><div><dt>${l('receipts')}</dt><dd>${num(state.receipts?.length||0)}</dd></div><div><dt>${l('campaigns')}</dt><dd>${num(state.campaigns.length)}</dd></div><div><dt>${l('outcomes')}</dt><dd>${num(state.results.length+(state.merchantFlow?.outcomes?.length||0))}</dd></div></dl><button class="text-button" data-action="open-workflow" data-step="8">${l('outcomes')}</button></aside></div>`;
}
